"""What the Omnix system map says: nodes, runtime edges and flows, written by hand.

scripts/system_map.py builds docs/architecture/omnix-system-map.{json,html} from this file. Feature
dependency and mount edges are not listed here: the build reads them from the feature catalog and each
feature.py, so they cannot drift. Everything else is a reading of the code; src/tests/scripts/test_system_map.py
fails when a cited path disappears, a flow hop has no edge, or the committed map is not a fresh build.
"""
from __future__ import annotations

LAYERS = [
    {"id": "client", "label": "Browser & desktop", "color": "#3b82f6"},
    {"id": "edge", "label": "Composition & edge", "color": "#8b5cf6"},
    {"id": "platform", "label": "Platform capabilities", "color": "#0ea5e9"},
    {"id": "apps", "label": "Apps", "color": "#10b981"},
    {"id": "kernel", "label": "Shared kernel", "color": "#f59e0b"},
    {"id": "data", "label": "Data", "color": "#ef4444"},
    {"id": "gpu", "label": "Local model services", "color": "#ec4899"},
    {"id": "external", "label": "External providers", "color": "#64748b"},
]


def node(id, label, layer, summary, paths, *, feature=None, port=None, key_files=(), invariants=(), tests=(), docs=()):
    n = {"id": id, "label": label, "layer": layer, "summary": summary, "paths": list(paths)}
    if feature:
        n["feature_id"] = feature
    if port:
        n["port"] = port
    if key_files:
        n["key_files"] = list(key_files)
    if invariants:
        n["invariants"] = list(invariants)
    if tests:
        n["tests"] = list(tests)
    if docs:
        n["docs"] = list(docs)
    return n


